import re

def parse(lines):
    rows = []
    used = []
    skip = []
    kv = {}
    kvl = []
    section = ''
    tok = re.compile(r'^-XX:(?P<sign>[+-])?(?P<name>\w+)(?:=(?P<val>.*))?$')
    for i, ln in enumerate(lines):
        s = ln.strip()
        if not s:
            continue
        m = re.match(r'^([A-Za-z][\w -]*):\s*$', s)
        if m:
            section = m.group(1)
            skip.append(i)
            continue
        m = re.match(r'^(Command line|Attaching to process[^:]*):\s*(.*)$', s)
        if m and not s.startswith('-'):
            kv[m.group(1)] = m.group(2)
            kvl.append(i)
            continue
        got = False
        for t in s.split():
            m = tok.match(t)
            if not m:
                continue
            got = True
            if m.group('sign') == '+':
                v = 'true'
            elif m.group('sign') == '-':
                v = 'false'
            else:
                v = m.group('val') if m.group('val') is not None else ''
            rows.append({'section': section, 'flag': m.group('name'), 'value': v})
        if got:
            used.append(i)
    blocks = []
    if rows:
        blocks.append({'name': 'flags', 'kind': 'table', 'lines': used, 'records': rows})
    if kv:
        blocks.append({'name': 'info', 'kind': 'kv', 'lines': kvl, 'records': [kv]})
    return {'blocks': blocks, 'skip': skip}
